+
+/**
+ * The same behaviour as {@link ContactViewTest}, checked in a real browser.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator heading() {
+        return page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setLevel(1)).first();
+    }
+
+    private Locator link(String text) {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName(text));
+    }
+
+    private Locator button(String text) {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(text));
+    }
+
+    /** The leave-confirmation dialog, told apart from Vaadin's own dev-mode dialogs. */
+    private Locator leaveDialog() {
+        return page.locator("vaadin-dialog")
+                .filter(new Locator.FilterOptions().setHas(button("Discard")));
+    }
+
+    private Locator grid() {
+        return page.locator("vaadin-grid");
+    }
+
+    private String cellContent(int row, int column) {
+        return new GridElement(grid()).findCell(row, column).orElseThrow()
+                .getCellContentLocator().textContent();
+    }
+
+    @Test
+    void view_showsHeadingLinkAndEnabledSend() {
+        assertThat(heading()).hasText("Contact");
+        assertThat(link("About")).isVisible();
+        assertThat(grid()).isVisible();
+        send().assertEnabled();
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+    }
+
+    @Test
+    void emptyForm_send_showsErrors() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+        new NotificationElement(page).assertClosed();
+        send().assertEnabled();
+    }
+
+    @Test
+    void invalidEmail_showsError() {
+        name().setValue("Ada");
+        email().setValue("nope");
+        message().setValue("Hi");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValid();
+        message().assertValid();
+        // Nothing was sent, and nothing the user typed was cleared.
+        name().assertValue("Ada");
+        assertThat(grid()).not().containsText("Ada");
+    }
+
+    @Test
+    void tooLongMessage_showsError() {
+        name().setValue("Ada");
+        phone().setValue("123");
+        message().setValue("x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+    }
+
+    @Test
+    void phoneOnly_isEnough() {
+        name().setValue("Ada");
+        phone().setValue("+358 40 123");
+        message().setValue("Call me");
+        send().click();
+
+        email().assertValid();
+        assertThat(grid()).containsText("Call me");
+    }
+
+    @Test
+    void validForm_sendsClearsAndDisablesSend() {
+        name().setValue("Ada Lovelace");
+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+        send().click();
+
+        assertThat(NotificationElement.getByText(page, "Message sent").getLocator()).isVisible();
+
+        assertThat(grid()).containsText("Ada Lovelace");
+        assertThat(grid()).containsText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("B");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterKey_sends() {
+        name().setValue("Ada");
+        phone().setValue("123456");
+        message().setValue("Sent with Enter");
+        message().getInputLocator().press("Enter");
+
+        assertThat(NotificationElement.getByText(page, "Message sent").getLocator()).isVisible();
+        assertThat(grid()).containsText("Sent with Enter");
+    }
+
+    @Test
+    void messages_areNewestFirst_andSurviveLeavingTheView() {
+        name().setValue("First");
+        phone().setValue("111");
+        message().setValue("one");
+        send().click();
+        assertThat(grid()).containsText("First");
+
+        name().setValue("Second");
+        phone().setValue("222");
+        message().setValue("two");
+        send().click();
+        assertThat(grid()).containsText("Second");
+
+        assertEquals("Second", cellContent(0, 0));
+        assertEquals("two", cellContent(0, 1));
+        assertEquals("First", cellContent(1, 0));
+
+        // Away and back: still there.
+        link("About").click();
+        assertThat(heading()).hasText("About");
+        link("Contact").click();
+        assertThat(heading()).hasText("Contact");
+        assertThat(grid()).containsText("Second");
+        assertThat(grid()).containsText("First");
+    }
+
+    @Test
+    void leavingWithInput_asksFirst_keepEditing() {
+        name().setValue("Ada");
+        link("About").click();
+
+        assertThat(button("Discard")).isVisible();
+        assertThat(leaveDialog()).hasCount(1);
+        assertThat(heading()).hasText("Contact");
+
+        button("Keep editing").click();
+
+        assertThat(leaveDialog()).hasCount(0);
+        assertThat(heading()).hasText("Contact");
+        name().assertValue("Ada");
+    }
+
+    @Test
+    void leavingWithInput_discard() {
+        message().setValue("half written");
+        link("About").click();
+
+        assertThat(button("Discard")).isVisible();
+        assertThat(leaveDialog()).hasCount(1);
+        button("Discard").click();
+
+        assertThat(heading()).hasText("About");
+    }
+
+    @Test
+    void leavingWithEmptyForm_isNotInterrupted() {
+        link("About").click();
+
+        assertThat(heading()).hasText("About");
+        assertThat(button("Discard")).hasCount(0);
+        assertThat(button("Keep editing")).hasCount(0);
+    }
+}
