+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        lookUpFields();
+    }
+
+    private void lookUpFields() {
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @Test
+    void view_hasHeadingLinkFormAndGrid() {
+        assertTrue($(H1.class).withText("Contact").exists());
+        assertTrue($(RouterLink.class).withText("About").exists());
+        assertTrue($(Grid.class).exists());
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled(), "Send must be enabled on an untouched form");
+    }
+
+    @Test
+    void aboutLink_navigatesWithEmptyForm() {
+        test($(RouterLink.class).withText("About").single()).click();
+        assertFalse($(Dialog.class).exists(), "No dialog when there is nothing to lose");
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void emptyForm_send_reportsNameMessageAndContact() {
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidEmail_isReported() {
+        fill("Ada", "not-an-address", "", "Hello");
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals(0, test(grid()).size());
+        // What the user typed stays put.
+        assertEquals("Ada", name.getValue());
+        assertEquals("not-an-address", email.getValue());
+        assertEquals("Hello", message.getValue());
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void exactly500Characters_isAccepted() {
+        fill("Ada", "ada@example.com", "", "x".repeat(500));
+        test(send).click();
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void phoneOnly_isEnough() {
+        fill("Ada", "", "+358 40 123", "Call me");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void emailOnly_isEnough() {
+        fill("Ada", "ada@example.com", "", "Mail me");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_sendsAndResets() {
+        fill("Ada Lovelace", "ada@example.com", "", "Hello there");
+        test(send).click();
+
+        assertTrue($(Notification.class).exists());
+        assertTrue(test($(Notification.class).first()).getText().contains("Message sent"));
+
+        var grid = test(grid());
+        assertEquals(1, grid.size());
+        assertEquals("Ada Lovelace", grid.getCellText(0, 0));
+        assertEquals("Hello there", grid.getCellText(0, 1));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(send.isEnabled(), "Send is disabled right after a successful send");
+        test(name).setValue("B");
+        assertTrue(send.isEnabled(), "Send is enabled again after the next edit");
+    }
+
+    @Test
+    void failedSendAfterASuccessfulOne_showsNoNotification() {
+        fill("Ada", "ada@example.com", "", "Hello");
+        test(send).click();
+        assertTrue($(Notification.class).exists());
+
+        // Editing enables Send again; this attempt is not valid.
+        test(name).setValue("Ada");
+        test(send).click();
